const handlers = new Map();                    // element kind -> handler(element, visitor)
const fallback = (e) => { throw new Error(`unhandled ${e.constructor.name}`); };
const visit = (e, visitor) =>
    (handlers.get(e.constructor) ?? fallback)(e, visitor);

handlers.set(Circle, (c, v) => { v.total += Math.PI * c.r ** 2; });
handlers.set(UnionShape, (u, v) => { visit(u.a, v); visit(u.b, v); });   // new kind, existing code untouched
